+  auto origins = LinearLayout(LinearLayout::BasesT{},
+                              standardOutDimPairs(ctx, shapePerCTA),
+                              /*requireSurjective=*/false) *
+                 getCGALayout(type.getEncoding()).getLinearLayout();
